insert into public.facilities (id, icon, surface, on_home, hours_label, sort, name_nl, name_en, name_de, summary_nl, summary_en, summary_de, description_nl, description_en, description_de, hours_nl, hours_en, hours_de, access_nl, access_en, access_de, location_nl, location_en, location_de) values
  ('chickens', 'chicken', 'stro', true, 'when', 1, 'De kippen', 'The chickens', 'Die Hühner', 'Eieren rapen en mee helpen voeren.', 'Collect eggs and help feed them.', 'Eier sammeln und beim Füttern helfen.', 'Help mee met voeren en kijk of er al eieren liggen. De kippen lopen vrij over het erf.', 'Help feed the chickens and see if they have laid any eggs yet. They roam freely around the farmyard.', 'Hilf beim Füttern und schau, ob schon Eier im Nest liegen. Die Hühner laufen frei über den Hof.', 'elke ochtend voeren, [tijd]', 'feeding every morning, [time]', 'Füttern jeden Morgen, [Uhrzeit]', 'vlak pad tot aan het hok', 'level path up to the coop', 'ebener Weg bis zum Stall', 'naast Weide A', 'next to Meadow A', 'neben Wiese A'),
  ('playground', 'tractor', 'gras', true, 'when', 2, 'Speelweide met tractor', 'Play meadow with tractor', 'Spielwiese mit Traktor', 'Klimmen, rennen en spelen op de oude tractor.', 'Climb, run and play on the old tractor.', 'Klettern, toben und spielen auf dem alten Traktor.', 'Klimmen op de oude tractor, rennen, voetballen. Ouders zien alles vanaf de picknicktafels.', 'Climb on the old tractor, run around, play football. Parents can keep an eye on everything from the picnic tables.', 'Auf den alten Traktor klettern, rennen, Fußball spielen. Eltern sehen von den Picknicktischen aus alles.', 'de hele dag, tot zonsondergang', 'all day, until sunset', 'den ganzen Tag, bis Sonnenuntergang', 'gras, deels hobbelig', 'grass, partly bumpy', 'Rasen, teils uneben', 'tussen Weide A en Weide B', 'between Meadow A and Meadow B', 'zwischen Wiese A und Wiese B'),
  ('pool', 'pool', 'water', true, 'open', 3, 'Buitenzwembad', 'Outdoor pool', 'Freibad', 'Even afkoelen na een dag op het erf.', 'Cool off after a day on the farm.', 'Abkühlen nach einem Tag auf dem Hof.', 'Even afkoelen na een dag op het erf. Met een ondiep deel voor de kleintjes.', 'Cool off after a day on the farm. With a shallow part for the little ones.', 'Abkühlen nach einem Tag auf dem Hof. Mit einem flachen Bereich für die Kleinen.', '[maand] t/m [maand], [tijden]', '[month] to [month], [times]', '[Monat] bis [Monat], [Zeiten]', '[tillift ja/nee, Bert controleert]', '[pool hoist yes/no, Bert will check]', '[Lifter ja/nein, Bert prüft das]', 'naast de camperplaatsen', 'next to the motorhome pitches', 'neben den Wohnmobilstellplätzen'),
  ('shop', 'shop', 'stro', false, 'open', 4, 'Het winkeltje', 'The farm shop', 'Der Hofladen', 'Verse eieren, melk, kaas en jam van boeren uit de buurt.', 'Fresh eggs, milk, cheese and jam from local farmers.', 'Frische Eier, Milch, Käse und Marmelade von Bauern aus der Gegend.', 'Verse eieren, melk, kaas en jam van boeren uit de buurt. Ook voor de vergeten tandenborstel.', 'Fresh eggs, milk, cheese and jam from local farmers. Also for the toothbrush you forgot.', 'Frische Eier, Milch, Käse und Marmelade von Bauern aus der Gegend. Auch für die vergessene Zahnbürste.', '[tijden], bij de receptie', '[times], at reception', '[Zeiten], an der Rezeption', 'drempelvrij', 'step-free', 'stufenlos', 'bij de ingang, in de receptie', 'by the entrance, in the reception building', 'am Eingang, in der Rezeption'),
  ('canteen', 'barn', 'stro', true, 'open', 5, 'Kantine in de oude melkstal', 'Canteen in the old milking parlour', 'Kantine im alten Melkstall', 'Met een winkeltje vol producten van lokale boeren.', 'With a little shop full of produce from local farms.', 'Mit einem kleinen Laden voller Produkte von Höfen aus der Gegend.', 'Waar vroeger de koeien gemolken werden, drink je nu koffie. Met spelletjes voor regenachtige dagen.', 'Where the cows were once milked, you can now enjoy a coffee. With games for rainy days.', 'Wo früher die Kühe gemolken wurden, trinkst du jetzt Kaffee. Mit Spielen für Regentage.', '[tijden]', '[times]', '[Zeiten]', 'ingang met hellingbaan', 'entrance with a ramp', 'Eingang mit Rampe', 'midden op het erf', 'in the middle of the farmyard', 'mitten auf dem Hof'),
  ('sanitary', 'shower', 'gras', false, 'open', 6, 'Sanitair & wasruimte', 'Toilets, showers & laundry', 'Sanitär & Waschraum', 'Warme douches, een familiedouche en wasmachines.', 'Hot showers, a family shower and washing machines.', 'Warme Duschen, eine Familiendusche und Waschmaschinen.', 'Warme douches, een familiedouche, een babyruimte en wasmachines.', 'Hot showers, a family shower, a baby room and washing machines.', 'Warme Duschen, eine Familiendusche, ein Babyraum und Waschmaschinen.', 'dag en nacht', 'day and night', 'Tag und Nacht', 'aangepaste douche en toilet', 'accessible shower and toilet', 'barrierefreie Dusche und Toilette', 'tussen Weide A en Weide B', 'between Meadow A and Meadow B', 'zwischen Wiese A und Wiese B')
insert into public.events (id, kind, age_group, start_time, recurrence, status, sample, title_nl, title_en, title_de, description_nl, description_en, description_de, location_nl, location_en, location_de) values
  ('kippen-voeren', 'animals', 'all', '09:00', '{"type":"daily","from":"2026-04-01"}'::jsonb, 'published', true, 'Kippen voeren', 'Feeding the chickens', 'Hühner füttern', 'Help mee met voeren en kijk of er al eieren liggen. Laarzen aan!', 'Help feed them and see if there are any eggs yet. Boots on!', 'Hilf beim Füttern und schau, ob schon Eier da sind. Gummistiefel an!', 'Kippenhok', 'Chicken coop', 'Hühnerstall'),
  ('speurtocht', 'play', 'kids', '14:00', '{"type":"weekly","weekdays":[1],"from":"2026-04-01"}'::jsonb, 'published', true, 'Speurtocht over het erf', 'Farmyard treasure hunt', 'Schnitzeljagd über den Hof', 'Zoek de verstopte hoefijzers. Wie ze alle tien vindt, mag de tractor toeteren.', 'Find the hidden horseshoes. Whoever finds all ten gets to honk the tractor horn.', 'Finde die versteckten Hufeisen. Wer alle zehn findet, darf die Traktorhupe drücken.', 'Speelweide', 'Play meadow', 'Spielwiese'),
  ('waterspelletjes', 'pool', 'kids', '15:00', '{"type":"weekly","weekdays":[2],"from":"2026-04-01"}'::jsonb, 'published', true, 'Waterspelletjes', 'Water games', 'Wasserspiele', 'Spetteren, duiken naar ringen en een wedstrijdje drijven.', 'Splashing, diving for rings and a floating contest.', 'Planschen, nach Ringen tauchen und ein Wettschwimmen auf dem Rücken.', 'Zwembad', 'Pool', 'Freibad'),
  ('tractor-toer', 'play', 'all', '10:30', '{"type":"weekly","weekdays":[3],"from":"2026-04-01"}'::jsonb, 'published', true, 'Tractor-toer met Bert', 'Tractor ride with Bert', 'Traktorfahrt mit Bert', 'Een rondje over het land in de aanhanger. Bert vertelt, de kinderen zwaaien.', 'A ride around the fields in the trailer. Bert tells stories, the children wave.', 'Eine Runde über die Felder im Anhänger. Bert erzählt, die Kinder winken.', 'Speelweide', 'Play meadow', 'Spielwiese'),
  ('pannenkoeken', 'food', 'all', '17:00', '{"type":"weekly","weekdays":[3],"from":"2026-04-01"}'::jsonb, 'published', true, 'Pannenkoeken bakken', 'Pancake baking', 'Pfannkuchen backen', 'Met eieren van onze eigen kippen. Opgeven bij de receptie.', 'With eggs from our own chickens. Sign up at reception.', 'Mit Eiern von unseren eigenen Hühnern. Anmeldung an der Rezeption.', 'Oude melkstal', 'Old milking parlour', 'Alter Melkstall'),
  ('eieren-zoeken', 'animals', 'toddlers', '14:00', '{"type":"weekly","weekdays":[4],"from":"2026-04-01"}'::jsonb, 'published', true, 'Eieren zoeken voor de kleintjes', 'Egg hunt for little ones', 'Eiersuche für die Kleinen', 'Samen met papa of mama de nesten langs. Wie vindt het eerste ei?', 'Visit the nests together with mum or dad. Who finds the first egg?', 'Mit Mama oder Papa die Nester abklappern. Wer findet das erste Ei?', 'Kippenhok', 'Chicken coop', 'Hühnerstall'),
  ('kampvuur', 'food', 'all', '19:30', '{"type":"weekly","weekdays":[5],"from":"2026-04-01"}'::jsonb, 'published', true, 'Kampvuur met marshmallows', 'Campfire with marshmallows', 'Lagerfeuer mit Marshmallows', 'Verhalen over vroeger op de boerderij, en een stokje met een marshmallow.', 'Stories about the old days on the farm, and a stick with a marshmallow.', 'Geschichten von früher auf dem Hof und ein Stock mit Marshmallow.', 'Erf', 'Farmyard', 'Hof'),
  ('boerengolf', 'play', 'adults', '11:00', '{"type":"weekly","weekdays":[6],"from":"2026-04-01"}'::jsonb, 'published', true, 'Boerengolf', 'Farm golf', 'Bauerngolf', 'Golf met een klomp aan een stok. Niemand wint, iedereen lacht.', 'Golf with a clog on a stick. Nobody wins, everybody laughs.', 'Golf mit einem Holzschuh am Stock. Keiner gewinnt, alle lachen.', 'Speelweide', 'Play meadow', 'Spielwiese'),
  ('zwemmen-zaterdag', 'pool', 'all', '15:00', '{"type":"weekly","weekdays":[6],"from":"2026-04-01"}'::jsonb, 'published', true, 'Zwemmiddag voor het hele gezin', 'Family swimming afternoon', 'Schwimmnachmittag für die ganze Familie', 'Met badmeester. Kinderen tot 8 jaar met een volwassene.', 'With a lifeguard. Children under 8 with an adult.', 'Mit Bademeister. Kinder unter 8 Jahren mit einem Erwachsenen.', 'Zwembad', 'Pool', 'Freibad'),
  ('boerenontbijt', 'food', 'all', '10:00', '{"type":"weekly","weekdays":[7],"from":"2026-04-01"}'::jsonb, 'published', true, 'Boerenontbijt', 'Farmhouse breakfast', 'Bauernfrühstück', 'Vers brood, eieren van het erf en jam uit het winkeltje.', 'Fresh bread, eggs from the farmyard and jam from the shop.', 'Frisches Brot, Eier vom Hof und Marmelade aus dem Hofladen.', 'Oude melkstal', 'Old milking parlour', 'Alter Melkstall')
insert into public.jokes (id, active, text_nl, text_en, text_de) values
  ('rooster-alarm', true, 'Onze haan is de beste wekker van het land. Alleen snoozen zit er niet op.', 'Our rooster has never once pressed snooze. We''ve checked.', 'Unser Hahn kennt keinen Sonntag. Und keine Schlummertaste.'),
  ('chicken-crossing', true, 'Waarom stak de kip het erf over? Om te kijken wie er in haar plekje stond.', 'Why did the chicken cross the farmyard? To inspect your tent pegs, of course.', 'Warum läuft das Huhn über den Hof? Es macht die Platzkontrolle.'),
  ('tractor-age', true, 'De tractor is ouder dan Bert. Dat zegt de tractor tenminste.', 'Bert says the tractor is vintage. The tractor says Bert is.', 'Der Traktor hat mehr Stunden auf dem Buckel als Bert. Behauptet zumindest der Traktor.'),
  ('wifi', true, 'De wifi is hier soms zwak. De verbinding met de natuur is altijd sterk.', 'The wifi can be patchy here. The stars, however, have full signal.', 'Das WLAN ist manchmal schwach. Dafür haben die Sterne hier vollen Empfang.'),
  ('weekend-eggs', true, 'Verse eieren bij het ontbijt? Onze kippen werken ook in het weekend.', 'Fresh eggs on a Sunday? Our hens don''t do days off.', 'Frische Eier am Sonntag? Unsere Hühner haben keinen freien Tag. Wir haben gefragt.')
